G=load()

def transform(g):
    h,w=len(g),len(g[0])
    # shapes: 3x3 ring of 3s, center 2
    shapes=[]
    for r in range(1,h-1):
        for c in range(1,w-1):
            if g[r][c]==2 and all(g[r+dr][c+dc]==3 for dr in(-1,0,1) for dc in(-1,0,1) if (dr,dc)!=(0,0)):
                shapes.append((r,c))
    sb={ (r,c) for r,c in shapes }
    inshape=set()
    for r,c in shapes:
        for dr in(-1,0,1):
            for dc in(-1,0,1):
                inshape.add((r+dr,c+dc))
    # lines: rows/cols with no zeros and at least one 2
    hrows=[r for r in range(h) if all(g[r][c]!=0 for c in range(w)) and any(g[r][c]==2 for c in range(w))]
    vcols=[c for c in range(w) if all(g[r][c]!=0 for r in range(h)) and any(g[r][c]==2 for r in range(h))]
    out=[row[:] for row in g]
    for r,c in shapes:
        if r in hrows:  # shape on horizontal line; stamps on other hlines
            for L in hrows:
                if L==r: continue
                for dr in(-1,0,1):
                    for dc in(-1,0,1):
                        p=(L+dr,c+dc)
                        if p not in inshape and (dr,dc)!=(0,0):
                            rr,cc=p
                            out[rr][cc]=1
            # ray: full column c, skip shapes
            for rr in range(h):
                if (rr,c) not in inshape and rr not in hrows:
                    out[rr][c]=1
        elif c in vcols:
            for L in vcols:
                if L==c: continue
                for dr in(-1,0,1):
                    for dc in(-1,0,1):
                        p=(r+dr,L+dc)
                        if p not in inshape and (dr,dc)!=(0,0):
                            rr,cc=p
                            out[rr][cc]=1
            for cc in range(w):
                if (r,cc) not in inshape and cc not in vcols:
                    out[r][cc]=1
    return out

